        return {(3, 5): cls.protocol_3_5_handler}
    elif isinstance(protocol_version, tuple) and len(protocol_version) == 2:
        if protocol_version in cls.supported_protocol_versions:
            return {protocol_version: cls.supported_protocol_versions[protocol_version]}
        else:
